begin;

create table public.mobile_media_assets (
  id uuid primary key default extensions.gen_random_uuid(),
  app_user_id uuid not null references public.app_users(id) on delete restrict,
  kind text not null check(kind in ('image','video')),
  purpose text not null check(purpose in ('fan_post','fan_clip','dm','certification')),
  content_type text not null check(content_type in ('image/jpeg','image/png','image/webp','video/mp4','video/quicktime')),
  expected_byte_size integer not null check(expected_byte_size between 1 and 52428800),
  actual_byte_size integer,
  storage_path text not null unique,
  thumbnail_path text not null unique,
  state text not null default 'uploading' check(state in ('uploading','pending','processing','ready','rejected','cancelled')),
  asset_version integer not null default 1 check(asset_version>0),
  request_id uuid not null,
  request_hash text not null,
  width integer, height integer, duration_seconds numeric,
  failure_code text, retry_at timestamptz,
  upload_expires_at timestamptz not null default clock_timestamp()+interval '15 minutes',
  storage_token_expires_at timestamptz,
  ready_at timestamptz, created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default clock_timestamp(),
  attached_type text check(attached_type in ('fan_post','fan_clip','dm_message','certification')),
  attached_id uuid, attached_version integer, position smallint,
  access_scope text not null default 'owner' check(access_scope in ('owner','fan_post','fan_clip','dm','certification')),
  cleanup_requested_at timestamptz, cleanup_retry_at timestamptz, cleanup_generation bigint not null default 0, storage_deleted_at timestamptz,
  unique(app_user_id,request_id),
  check((kind='image' and expected_byte_size<=8388608 and content_type like 'image/%') or(kind='video' and content_type like 'video/%')),
  check(purpose not in('fan_post','certification') or kind='image'),
  check((state<>'ready') or(width>0 and height>0 and actual_byte_size>0)),
  check((kind='image' and duration_seconds is null)or(kind='video' and duration_seconds>0 and duration_seconds<=60)),
  check((attached_id is null)=(attached_type is null))
);
create index mobile_media_assets_owner_idx on public.mobile_media_assets(app_user_id,created_at desc);
create index mobile_media_assets_cleanup_idx on public.mobile_media_assets(cleanup_retry_at,created_at) where storage_deleted_at is null;

create table public.mobile_media_validation_jobs (
  id uuid primary key default extensions.gen_random_uuid(),
  asset_id uuid not null references public.mobile_media_assets(id) on delete cascade,
  asset_version integer not null,
  status text not null default 'queued' check(status in ('queued','processing','retrying','completed','rejected','cancelled')),
  attempts integer not null default 0 check(attempts between 0 and 4),
  lease_expires_at timestamptz, next_attempt_at timestamptz not null default clock_timestamp(),
  created_at timestamptz not null default clock_timestamp(), updated_at timestamptz not null default clock_timestamp(),
  unique(asset_id,asset_version)
);
create index mobile_media_validation_jobs_claim_idx on public.mobile_media_validation_jobs(next_attempt_at,created_at) where status in('queued','retrying','processing');

alter table public.mobile_media_assets enable row level security; alter table public.mobile_media_assets force row level security;
alter table public.mobile_media_validation_jobs enable row level security; alter table public.mobile_media_validation_jobs force row level security;
revoke all on public.mobile_media_assets,public.mobile_media_validation_jobs from public,anon,authenticated,service_role;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('mobile-media','mobile-media',false,52428800,array['image/jpeg','image/png','image/webp','video/mp4','video/quicktime'])
on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;

create function public.reserve_owned_mobile_media(p_app_user_id uuid,p_kind text,p_purpose text,p_content_type text,p_byte_size integer,p_request_id uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.mobile_media_assets%rowtype; v_id uuid:=extensions.gen_random_uuid(); v_hash text; v_ext text;
begin
  perform public.fan_web_lock_active_user(p_app_user_id);
  if p_request_id is null or p_kind not in('image','video') or p_purpose not in('fan_post','fan_clip','dm','certification')
    or p_content_type not in('image/jpeg','image/png','image/webp','video/mp4','video/quicktime') or p_byte_size not between 1 and 52428800
    or(p_kind='image' and(p_content_type not like 'image/%' or p_byte_size>8388608))or(p_kind='video' and p_content_type not like 'video/%')
    or(p_purpose in('fan_post','certification')and p_kind<>'image') then raise exception 'MEDIA_INVALID_INPUT'; end if;
  v_hash:=md5(p_kind||':'||p_purpose||':'||p_content_type||':'||p_byte_size::text);
  select * into a from public.mobile_media_assets where app_user_id=p_app_user_id and request_id=p_request_id;
  if found then if a.request_hash<>v_hash or a.state<>'uploading'or a.upload_expires_at<=clock_timestamp()then raise exception 'MEDIA_CONFLICT'; end if; return jsonb_build_object('assetId',a.id,'storagePath',a.storage_path,'expiresAt',a.upload_expires_at,'replayed',true); end if;
  if(select count(*)from public.mobile_media_assets where app_user_id=p_app_user_id and created_at>clock_timestamp()-interval '1 minute')>=20 then raise exception 'MEDIA_RATE_LIMITED'; end if;
  v_ext:=case p_content_type when'image/jpeg'then'jpg' when'image/png'then'png' when'image/webp'then'webp' when'video/quicktime'then'mov'else'mp4'end;
  insert into public.mobile_media_assets(id,app_user_id,kind,purpose,content_type,expected_byte_size,storage_path,thumbnail_path,request_id,request_hash)
  values(v_id,p_app_user_id,p_kind,p_purpose,p_content_type,p_byte_size,p_app_user_id::text||'/'||v_id::text||'/original.'||v_ext,p_app_user_id::text||'/'||v_id::text||'/thumbnail.webp',p_request_id,v_hash) returning * into a;
  return jsonb_build_object('assetId',a.id,'storagePath',a.storage_path,'expiresAt',a.upload_expires_at,'replayed',false);
end $$;

create function public.record_owned_mobile_media_upload_token(p_app_user_id uuid,p_asset_id uuid,p_token_expires_at timestamptz)returns void language plpgsql security definer set search_path=''as $$begin perform public.fan_web_lock_active_user(p_app_user_id);if p_token_expires_at is null or p_token_expires_at<=clock_timestamp()or p_token_expires_at>clock_timestamp()+interval'3 hours'then raise exception'MEDIA_CONFLICT';end if;update public.mobile_media_assets set storage_token_expires_at=greatest(coalesce(storage_token_expires_at,p_token_expires_at),p_token_expires_at),updated_at=clock_timestamp()where id=p_asset_id and app_user_id=p_app_user_id and state='uploading';if not found then raise exception'MEDIA_CONFLICT';end if;end $$;

create function public.mobile_media_owned_json(a public.mobile_media_assets) returns jsonb language sql immutable set search_path='' as $$
 select jsonb_build_object('assetId',a.id,'state',a.state,'kind',a.kind,'purpose',a.purpose,'contentType',a.content_type,'byteSize',a.expected_byte_size,'assetVersion',a.asset_version,'width',a.width,'height',a.height,'durationSeconds',a.duration_seconds,'failureCode',a.failure_code,'retryAt',a.retry_at,'expiresAt',a.upload_expires_at) $$;
create function public.read_owned_mobile_media(p_app_user_id uuid,p_asset_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.mobile_media_assets%rowtype; begin perform public.fan_web_lock_active_user(p_app_user_id); select * into a from public.mobile_media_assets where id=p_asset_id and app_user_id=p_app_user_id; if not found then raise exception 'MEDIA_NOT_FOUND'; end if; return public.mobile_media_owned_json(a); end $$;

create function public.queue_owned_mobile_media_validation(p_app_user_id uuid,p_asset_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.mobile_media_assets%rowtype; j public.mobile_media_validation_jobs%rowtype; begin
 perform public.fan_web_lock_active_user(p_app_user_id); select * into a from public.mobile_media_assets where id=p_asset_id and app_user_id=p_app_user_id for update;
 if not found then raise exception 'MEDIA_NOT_FOUND'; end if; if a.state in('ready','rejected')then return public.mobile_media_owned_json(a);end if;
 if a.state='cancelled'or a.upload_expires_at<=clock_timestamp()then raise exception 'MEDIA_CONFLICT';end if;
 update public.mobile_media_assets set state='pending',updated_at=clock_timestamp()where id=a.id and state='uploading';
 insert into public.mobile_media_validation_jobs(asset_id,asset_version)values(a.id,a.asset_version)on conflict(asset_id,asset_version)do nothing;
 select * into j from public.mobile_media_validation_jobs where asset_id=a.id and asset_version=a.asset_version;
 return jsonb_build_object('assetId',a.id,'jobId',j.id,'state',j.status);
end $$;

create function public.claim_mobile_media_validation(p_asset_id uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare r record;begin
 with exhausted as(update public.mobile_media_validation_jobs set status='rejected',lease_expires_at=null,updated_at=clock_timestamp()where status='processing'and lease_expires_at<=clock_timestamp()and attempts>=4 returning asset_id,asset_version)
 update public.mobile_media_assets a set state='rejected',failure_code='MEDIA_VALIDATION_TIMEOUT',asset_version=a.asset_version+1,cleanup_requested_at=clock_timestamp(),cleanup_retry_at=greatest(clock_timestamp(),coalesce(a.storage_token_expires_at,a.upload_expires_at)+interval'5 minutes'),updated_at=clock_timestamp()from exhausted e where a.id=e.asset_id and a.asset_version=e.asset_version and a.state='processing';
 update public.mobile_media_validation_jobs set status='retrying',next_attempt_at=clock_timestamp(),lease_expires_at=null,updated_at=clock_timestamp()
 where status='processing'and lease_expires_at<=clock_timestamp()and attempts<4;
 with candidate as(select j.id from public.mobile_media_validation_jobs j join public.mobile_media_assets a on a.id=j.asset_id and a.asset_version=j.asset_version and a.state in('pending','processing') join public.app_users u on u.id=a.app_user_id and u.status='active'
   where(p_asset_id is null or a.id=p_asset_id)and j.status in('queued','retrying')and j.next_attempt_at<=clock_timestamp() order by j.next_attempt_at,j.created_at for update skip locked limit 1),
claimed as(update public.mobile_media_validation_jobs j set status='processing',attempts=j.attempts+1,lease_expires_at=clock_timestamp()+interval '3 minutes',updated_at=clock_timestamp()from candidate c where j.id=c.id returning j.*)
 select j.id job_id,a.* into r from claimed j join public.mobile_media_assets a on a.id=j.asset_id;
 if not found then return null;end if; update public.mobile_media_assets set state='processing',updated_at=clock_timestamp()where id=r.id and asset_version=r.asset_version and state in('pending','processing');
 return jsonb_build_object('jobId',r.job_id,'assetId',r.id,'assetVersion',r.asset_version,'state','processing','kind',r.kind,'purpose',r.purpose,'contentType',r.content_type,'byteSize',r.expected_byte_size,'storagePath',r.storage_path,'thumbnailPath',r.thumbnail_path,'width',r.width,'height',r.height,'durationSeconds',r.duration_seconds,'failureCode',r.failure_code,'retryAt',r.retry_at,'expiresAt',r.upload_expires_at);
end $$;

create function public.finish_mobile_media_validation(p_asset_id uuid,p_asset_version integer,p_job_id uuid,p_content_type text,p_width integer,p_height integer,p_duration_seconds numeric)returns void language plpgsql security definer set search_path=''as $$
declare n integer;begin update public.mobile_media_assets a set state='ready',content_type=p_content_type,actual_byte_size=expected_byte_size,width=p_width,height=p_height,duration_seconds=p_duration_seconds,ready_at=clock_timestamp(),failure_code=null,retry_at=null,updated_at=clock_timestamp()
 where a.id=p_asset_id and a.asset_version=p_asset_version and a.state='processing'and exists(select 1 from public.app_users u where u.id=a.app_user_id and u.status='active')and exists(select 1 from public.mobile_media_validation_jobs j where j.id=p_job_id and j.asset_id=a.id and j.asset_version=a.asset_version and j.status='processing');get diagnostics n=row_count;if n<>1 then raise exception'MEDIA_CONFLICT';end if;update public.mobile_media_validation_jobs set status='completed',lease_expires_at=null,updated_at=clock_timestamp()where id=p_job_id and status='processing';end $$;
create function public.reject_mobile_media_validation(p_asset_id uuid,p_asset_version integer,p_job_id uuid,p_error_code text)returns void language plpgsql security definer set search_path=''as $$begin update public.mobile_media_assets set state='rejected',failure_code=left(p_error_code,80),cleanup_requested_at=clock_timestamp(),cleanup_retry_at=greatest(clock_timestamp(),coalesce(storage_token_expires_at,upload_expires_at)+interval'5 minutes'),asset_version=asset_version+1,updated_at=clock_timestamp()where id=p_asset_id and asset_version=p_asset_version and state='processing'and exists(select 1 from public.mobile_media_validation_jobs where id=p_job_id and asset_id=p_asset_id and asset_version=p_asset_version and status='processing');if not found then raise exception'MEDIA_CONFLICT';end if;update public.mobile_media_validation_jobs set status='rejected',lease_expires_at=null,updated_at=clock_timestamp()where id=p_job_id;end $$;
create function public.retry_mobile_media_validation(p_asset_id uuid,p_asset_version integer,p_job_id uuid)returns void language plpgsql security definer set search_path=''as $$
declare tries integer;begin select attempts into tries from public.mobile_media_validation_jobs where id=p_job_id and asset_id=p_asset_id and asset_version=p_asset_version and status='processing'for update;if not found then raise exception'MEDIA_CONFLICT';end if;if tries>=4 then perform public.reject_mobile_media_validation(p_asset_id,p_asset_version,p_job_id,'MEDIA_VALIDATION_UNAVAILABLE');else update public.mobile_media_assets set state='pending',retry_at=clock_timestamp()+interval '1 minute',updated_at=clock_timestamp()where id=p_asset_id and asset_version=p_asset_version and state='processing';update public.mobile_media_validation_jobs set status='retrying',lease_expires_at=null,next_attempt_at=clock_timestamp()+interval '1 minute',updated_at=clock_timestamp()where id=p_job_id;end if;end $$;

create function public.cancel_owned_mobile_media(p_app_user_id uuid,p_asset_id uuid)returns void language plpgsql security definer set search_path=''as $$begin perform public.fan_web_lock_active_user(p_app_user_id);update public.mobile_media_assets set state='cancelled',asset_version=asset_version+1,cleanup_requested_at=clock_timestamp(),cleanup_retry_at=greatest(clock_timestamp(),coalesce(storage_token_expires_at,upload_expires_at)+interval'5 minutes'),updated_at=clock_timestamp()where id=p_asset_id and app_user_id=p_app_user_id and attached_id is null and state in('uploading','pending','processing','ready');if not found then raise exception'MEDIA_CONFLICT';end if;update public.mobile_media_validation_jobs set status='cancelled',lease_expires_at=null,updated_at=clock_timestamp()where asset_id=p_asset_id and status in('queued','processing','retrying');end $$;

create function public.authorize_mobile_media_read(p_app_user_id uuid,p_asset_id uuid,p_variant text)returns jsonb language plpgsql stable security definer set search_path=''as $$
declare a public.mobile_media_assets%rowtype; allowed boolean:=false;begin perform public.fan_web_lock_active_user(p_app_user_id);if p_variant not in('original','thumbnail')then raise exception'MEDIA_INVALID_INPUT';end if;select*into a from public.mobile_media_assets where id=p_asset_id and state='ready'and storage_deleted_at is null;if not found then return null;end if;
 allowed:=(a.app_user_id=p_app_user_id and a.access_scope in('owner','certification','fan_clip'))or(a.access_scope='fan_post'and a.attached_type='fan_post'and public.fan_web_content_visible(p_app_user_id,'fan_post',a.attached_id))or(a.access_scope='dm'and a.attached_type='dm_message'and exists(select 1 from public.social_dm_messages m join public.social_dm_conversations c on c.id=m.conversation_id where m.id=a.attached_id and p_app_user_id in(c.user_low_id,c.user_high_id)and not public.fan_web_blocked(c.user_low_id,c.user_high_id)and not exists(select 1 from public.social_dm_message_deletions d where d.message_id=m.id and d.app_user_id=p_app_user_id)));
 if not allowed then return null;end if;return jsonb_build_object('storagePath',case when p_variant='thumbnail'then a.thumbnail_path else a.storage_path end,'contentType',case when p_variant='thumbnail'then'image/webp'else a.content_type end);end $$;

create function public.attach_mobile_media(p_app_user_id uuid,p_asset_id uuid,p_purpose text,p_attached_type text,p_attached_id uuid,p_attached_version integer,p_position smallint)returns void language plpgsql security definer set search_path=''as $$begin update public.mobile_media_assets set attached_type=p_attached_type,attached_id=p_attached_id,attached_version=p_attached_version,position=p_position,access_scope=case when p_attached_type='fan_post'then'fan_post'when p_attached_type='dm_message'then'dm'else access_scope end,updated_at=clock_timestamp()where id=p_asset_id and app_user_id=p_app_user_id and purpose=p_purpose and state='ready'and storage_deleted_at is null and(attached_id is null or(attached_type=p_attached_type and attached_id=p_attached_id));if not found then raise exception'MEDIA_INVALID_ASSET';end if;end $$;

create function public.claim_mobile_media_cleanup(p_limit integer default 25)returns jsonb language plpgsql security definer set search_path=''as $$declare result jsonb;begin
 update public.mobile_media_assets a set state='cancelled',asset_version=asset_version+1,cleanup_requested_at=clock_timestamp(),cleanup_retry_at=greatest(clock_timestamp(),coalesce(a.storage_token_expires_at,a.upload_expires_at)+interval'5 minutes'),updated_at=clock_timestamp()where a.storage_deleted_at is null and a.attached_id is null and((a.state='uploading'and a.upload_expires_at<=clock_timestamp())or exists(select 1 from public.app_users u where u.id=a.app_user_id and u.status<>'active'));
 with due as(select id from public.mobile_media_assets where storage_deleted_at is null and cleanup_requested_at is not null and(cleanup_retry_at is null or cleanup_retry_at<=clock_timestamp())order by cleanup_retry_at nulls first,created_at for update skip locked limit least(greatest(p_limit,1),50)),claimed as(update public.mobile_media_assets a set cleanup_generation=cleanup_generation+1,cleanup_retry_at=clock_timestamp()+interval'5 minutes'from due where a.id=due.id returning a.id,a.storage_path,a.thumbnail_path,a.cleanup_generation)select jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object('assetId',id,'storagePath',storage_path,'thumbnailPath',thumbnail_path,'generation',cleanup_generation)),'[]'::jsonb))into result from claimed;return result;end $$;
create function public.finish_mobile_media_cleanup(p_asset_id uuid,p_generation bigint,p_succeeded boolean)returns void language plpgsql security definer set search_path=''as $$begin update public.mobile_media_assets set storage_deleted_at=case when p_succeeded then clock_timestamp()else storage_deleted_at end,cleanup_retry_at=case when p_succeeded then null else clock_timestamp()+interval'5 minutes'end where id=p_asset_id and cleanup_generation=p_generation and cleanup_requested_at is not null;end $$;

alter table public.social_dm_messages add column media_asset_id uuid references public.mobile_media_assets(id) on delete restrict;
alter table public.social_dm_messages drop constraint social_dm_messages_body_check;
alter table public.social_dm_messages add constraint social_dm_messages_content_check check(length(btrim(body))<=2000 and(length(btrim(body))>0 or media_asset_id is not null));

-- New overloads preserve existing text-only clients while binding one validated attachment atomically.
create function public.send_social_dm_message(p_app_user_id uuid,p_conversation_id uuid,p_body text,p_asset_id uuid,p_request_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$
declare d public.social_dm_conversations%rowtype;m public.social_dm_messages%rowtype;other_id uuid;h text:=md5(btrim(coalesce(p_body,''))||':'||coalesce(p_asset_id::text,''));allowed boolean;begin perform public.social_request_lock(p_app_user_id,p_request_id);if length(btrim(coalesce(p_body,'')))>2000 or(btrim(coalesce(p_body,''))=''and p_asset_id is null)then raise exception'SOCIAL_CONFLICT';end if;select*into d from public.social_dm_conversations where id=p_conversation_id;if not found or p_app_user_id not in(d.user_low_id,d.user_high_id)then raise exception'SOCIAL_NOT_FOUND';end if;other_id:=case when d.user_low_id=p_app_user_id then d.user_high_id else d.user_low_id end;perform public.social_lock_pair(p_app_user_id,other_id);select*into d from public.social_dm_conversations where id=p_conversation_id for update;if public.fan_web_blocked(p_app_user_id,other_id)then raise exception'SOCIAL_BLOCKED';end if;allowed:=d.status='accepted'or exists(select 1 from public.social_friendships f where f.user_low_id=d.user_low_id and f.user_high_id=d.user_high_id and f.status='accepted');if not allowed then raise exception'SOCIAL_FORBIDDEN';end if;select*into m from public.social_dm_messages where sender_id=p_app_user_id and request_id=p_request_id;if found then if m.payload_hash<>h or m.conversation_id<>p_conversation_id then raise exception'SOCIAL_IDEMPOTENCY_CONFLICT';end if;return jsonb_build_object('id',m.id,'createdAt',m.created_at,'assetId',m.media_asset_id,'replayed',true);end if;insert into public.social_dm_messages(conversation_id,sender_id,body,request_id,payload_hash,media_asset_id)values(p_conversation_id,p_app_user_id,btrim(coalesce(p_body,'')),p_request_id,h,p_asset_id)returning*into m;if p_asset_id is not null then perform public.attach_mobile_media(p_app_user_id,p_asset_id,'dm','dm_message',m.id,1,0::smallint);end if;return jsonb_build_object('id',m.id,'createdAt',m.created_at,'assetId',m.media_asset_id,'replayed',false);end $$;

create or replace function public.read_social_dm_messages(p_app_user_id uuid,p_conversation_id uuid,p_after timestamptz,p_after_id uuid,p_limit integer)returns jsonb language plpgsql stable security definer set search_path=''as $$
declare d public.social_dm_conversations%rowtype;begin perform public.fan_web_lock_active_user(p_app_user_id);select*into d from public.social_dm_conversations where id=p_conversation_id and p_app_user_id in(user_low_id,user_high_id);if not found then raise exception'SOCIAL_NOT_FOUND';end if;if public.fan_web_blocked(d.user_low_id,d.user_high_id)then raise exception'SOCIAL_BLOCKED';end if;return jsonb_build_object('messages',coalesce((select jsonb_agg(x.item order by x.created_at,x.id)from(select m.created_at,m.id,jsonb_build_object('id',m.id,'senderProfileId',m.sender_id,'text',m.body,'attachment',case when a.id is null then null else jsonb_build_object('assetId',a.id,'kind',a.kind)end,'createdAt',m.created_at,'reaction',(select r.reaction from public.social_dm_message_reactions r where r.message_id=m.id and r.app_user_id=p_app_user_id),'isMine',m.sender_id=p_app_user_id)item from public.social_dm_messages m left join public.mobile_media_assets a on a.id=m.media_asset_id and a.state='ready'and a.storage_deleted_at is null where m.conversation_id=p_conversation_id and not exists(select 1 from public.social_dm_message_deletions z where z.message_id=m.id and z.app_user_id=p_app_user_id)and(p_after is null or(m.created_at,m.id)>(p_after,p_after_id))order by m.created_at,m.id limit p_limit)x),'[]'::jsonb));end $$;

create or replace function public.fan_web_post_json(p_app_user_id uuid,p_post_id uuid,p_locale public.content_locale default'ko')returns jsonb language sql stable security definer set search_path=''as $$
select jsonb_build_object('id',p.id,'celebritySlug',c.slug,'body',p.body,'visibility',p.visibility,'revision',p.revision,'createdAt',p.created_at,'updatedAt',p.updated_at,'isOwner',coalesce(p.app_user_id=p_app_user_id,false),'author',jsonb_build_object('nickname',coalesce(nullif(btrim(pr.nickname),''),case when p_locale='ko'then'팬'else'Fan'end),'avatarUrl','/images/avatars/'||coalesce(a.selected_character_id,'star-pink')||'.webp'),'assets',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'width',x.width,'height',x.height)order by x.position)from(select id,width,height,position from public.content_assets where post_id=p.id and deleted_at is null and cleanup_requested_at is null and uploaded_at is not null union all select id,width,height,position from public.mobile_media_assets where attached_type='fan_post'and attached_id=p.id and state='ready'and storage_deleted_at is null)x),'[]'::jsonb),'likeCount',(select count(*)from public.fan_post_likes k join public.app_users u on u.id=k.app_user_id and u.status='active'where k.post_id=p.id and not public.fan_web_blocked(p_app_user_id,k.app_user_id)),'liked',exists(select 1 from public.fan_post_likes where post_id=p.id and app_user_id=p_app_user_id),'commentCount',(select count(*)from public.fan_post_comments x where x.post_id=p.id and public.fan_web_content_visible(p_app_user_id,'fan_post_comment',x.id)))from public.fan_posts p join public.celebrities c on c.id=p.celebrity_id left join public.user_profiles pr on pr.app_user_id=p.app_user_id left join public.app_user_avatars a on a.app_user_id=p.app_user_id where p.id=p_post_id and public.fan_web_content_visible(p_app_user_id,'fan_post',p.id)$$;

-- Common assets are accepted by the unchanged fan-post API. Legacy web assets remain valid.
create or replace function public.save_fan_post(p_app_user_id uuid,p_slug text,p_post_id uuid,p_body text,p_visibility text,p_asset_ids uuid[],p_expected_revision integer,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=''as $$
declare v_creator uuid;v_post public.fan_posts%rowtype;v_id uuid;v_hash text;v_body text:=btrim(coalesce(p_body,''));v_assets uuid[]:=coalesce(p_asset_ids,'{}'::uuid[]);v_valid integer;begin perform public.fan_web_lock_active_user(p_app_user_id);if p_visibility is null or p_visibility not in('public','members')or length(v_body)>5000 or cardinality(v_assets)>4 or cardinality(v_assets)<>(select count(distinct x)from unnest(v_assets)x)or(v_body=''and cardinality(v_assets)=0)then raise exception'FAN_WEB_INVALID_INPUT';end if;select id into v_creator from public.celebrities where slug=p_slug and status='published'and archived_at is null for share;if v_creator is null then raise exception'FAN_WEB_NOT_FOUND';end if;if p_visibility='members'and not public.fan_web_is_member(p_app_user_id,v_creator)then raise exception'FAN_WEB_FORBIDDEN';end if;v_hash:=encode(extensions.digest(jsonb_build_array(v_creator,v_body,p_visibility,v_assets)::text,'sha256'),'hex');if p_post_id is null then if p_idempotency_key is null then raise exception'FAN_WEB_INVALID_INPUT';end if;select*into v_post from public.fan_posts where app_user_id=p_app_user_id and idempotency_key=p_idempotency_key;if found then if v_post.create_request_hash<>v_hash then raise exception'FAN_WEB_CONFLICT';end if;return jsonb_build_object('id',v_post.id,'revision',v_post.revision,'replayed',true);end if;if(select count(*)from public.fan_posts where app_user_id=p_app_user_id and created_at>clock_timestamp()-interval'1 minute')>=10 then raise exception'FAN_WEB_RATE_LIMITED';end if;v_id:=extensions.gen_random_uuid();else select*into v_post from public.fan_posts where id=p_post_id and app_user_id=p_app_user_id and celebrity_id=v_creator for update;if not found or v_post.deleted_at is not null or v_post.hidden_at is not null then raise exception'FAN_WEB_NOT_FOUND';end if;if p_expected_revision is null or v_post.revision<>p_expected_revision then raise exception'FAN_WEB_CONFLICT';end if;v_id:=p_post_id;end if;
 perform 1 from public.mobile_media_assets where id=any(v_assets)order by id for update;select(select count(*)from public.content_assets where id=any(v_assets)and app_user_id=p_app_user_id and celebrity_id=v_creator and uploaded_at is not null and deleted_at is null and cleanup_requested_at is null and notice_id is null and(post_id=v_id or(post_id is null and expires_at>clock_timestamp())))+(select count(*)from public.mobile_media_assets where id=any(v_assets)and app_user_id=p_app_user_id and purpose='fan_post'and kind='image'and state='ready'and storage_deleted_at is null and(attached_id is null or(attached_type='fan_post'and attached_id=v_id)))into v_valid;if v_valid<>cardinality(v_assets)then raise exception'MEDIA_INVALID_ASSET';end if;
 if p_post_id is null then insert into public.fan_posts(id,celebrity_id,app_user_id,body,visibility,idempotency_key,create_request_hash)values(v_id,v_creator,p_app_user_id,v_body,p_visibility,p_idempotency_key,v_hash)returning*into v_post;else update public.fan_posts set body=v_body,visibility=p_visibility,revision=revision+1,updated_at=clock_timestamp()where id=v_id returning*into v_post;insert into public.content_write_events(app_user_id,kind)values(p_app_user_id,'post_edit');end if;
 update public.content_assets set deleted_at=clock_timestamp(),cleanup_requested_at=clock_timestamp(),cleanup_retry_at=clock_timestamp(),position=null where post_id=v_id and deleted_at is null and not(id=any(v_assets));update public.mobile_media_assets set state='cancelled',asset_version=asset_version+1,cleanup_requested_at=clock_timestamp(),cleanup_retry_at=greatest(clock_timestamp(),coalesce(storage_token_expires_at,upload_expires_at)+interval'5 minutes'),position=null where attached_type='fan_post'and attached_id=v_id and not(id=any(v_assets));update public.content_assets set position=null where post_id=v_id and id=any(v_assets);update public.mobile_media_assets set position=null where attached_type='fan_post'and attached_id=v_id and id=any(v_assets);update public.content_assets a set post_id=v_id,position=(s.ord-1)::smallint from unnest(v_assets)with ordinality s(id,ord)where a.id=s.id;update public.mobile_media_assets a set attached_type='fan_post',attached_id=v_id,attached_version=v_post.revision,access_scope='fan_post',position=(s.ord-1)::smallint,updated_at=clock_timestamp()from unnest(v_assets)with ordinality s(id,ord)where a.id=s.id;return jsonb_build_object('id',v_id,'revision',v_post.revision,'replayed',false);end $$;

create or replace function public.remove_fan_post(p_app_user_id uuid,p_post_id uuid)returns void language plpgsql security definer set search_path=''as $$begin perform public.fan_web_lock_active_user(p_app_user_id);perform 1 from public.fan_posts where id=p_post_id and app_user_id=p_app_user_id for update;if not found then raise exception'FAN_WEB_NOT_FOUND';end if;update public.fan_posts set deleted_at=clock_timestamp(),revision=revision+1,updated_at=clock_timestamp()where id=p_post_id and deleted_at is null;update public.content_assets set deleted_at=coalesce(deleted_at,clock_timestamp()),cleanup_requested_at=coalesce(cleanup_requested_at,clock_timestamp()),cleanup_retry_at=clock_timestamp()where post_id=p_post_id and storage_deleted_at is null;update public.mobile_media_assets set state='cancelled',asset_version=asset_version+1,cleanup_requested_at=coalesce(cleanup_requested_at,clock_timestamp()),cleanup_retry_at=greatest(clock_timestamp(),coalesce(storage_token_expires_at,upload_expires_at)+interval'5 minutes'),updated_at=clock_timestamp()where attached_type='fan_post'and attached_id=p_post_id and storage_deleted_at is null;end $$;

create function public.scrub_mobile_media_on_deletion()returns trigger language plpgsql security definer set search_path=''as $$begin if old.status='active'and new.status='disabled'then update public.mobile_media_assets set state='cancelled',asset_version=asset_version+1,cleanup_requested_at=clock_timestamp(),cleanup_retry_at=greatest(clock_timestamp(),coalesce(storage_token_expires_at,upload_expires_at)+interval'5 minutes'),updated_at=clock_timestamp()where app_user_id=new.id and storage_deleted_at is null;update public.mobile_media_validation_jobs set status='cancelled',lease_expires_at=null,updated_at=clock_timestamp()where asset_id in(select id from public.mobile_media_assets where app_user_id=new.id)and status in('queued','processing','retrying');end if;return new;end $$;
create trigger app_users_scrub_mobile_media_on_deletion after update of status on public.app_users for each row execute function public.scrub_mobile_media_on_deletion();

create or replace function public.account_deletion_storage_ready(p_app_user_id uuid,p_lease_token uuid)returns boolean language sql stable security definer set search_path=''as $$select exists(select 1 from public.account_deletion_requests where app_user_id=p_app_user_id and lease_token=p_lease_token and lease_until>clock_timestamp()and status='pending')and not exists(select 1 from public.account_deletion_objects where app_user_id=p_app_user_id and storage_deleted_at is null)and not exists(select 1 from public.content_assets where app_user_id=p_app_user_id and(storage_deleted_at is null or upload_settled_at is null))and not exists(select 1 from public.mobile_media_assets where app_user_id=p_app_user_id and storage_deleted_at is null)and not exists(select 1 from public.fan_private_uploads where app_user_id=p_app_user_id and expires_at>clock_timestamp())$$;

