grant execute on function public.reserve_owned_mobile_media(uuid,text,text,text,integer,uuid),public.record_owned_mobile_media_upload_token(uuid,uuid,timestamptz),public.read_owned_mobile_media(uuid,uuid),public.queue_owned_mobile_media_validation(uuid,uuid),public.claim_mobile_media_validation(uuid),public.finish_mobile_media_validation(uuid,integer,uuid,text,integer,integer,numeric),public.reject_mobile_media_validation(uuid,integer,uuid,text),public.retry_mobile_media_validation(uuid,integer,uuid),public.cancel_owned_mobile_media(uuid,uuid),public.authorize_mobile_media_read(uuid,uuid,text),public.claim_mobile_media_cleanup(integer),public.finish_mobile_media_cleanup(uuid,bigint,boolean),public.send_social_dm_message(uuid,uuid,text,uuid,uuid)to service_role;

